//! 🎟️ Qualification compares one original catalog row at a time and retains its exact metadata lease.
use semio_plugin_job::original_declared_tools::{DeclaredToolCatalogAlias,DeclaredToolCatalogSource,DeclaredToolRegistrationAlias,DeclaredToolRowKey,DeclaredToolRole};
use semio_framework_job::{StepContext,OriginalConstructionAdmission,OriginalSourceBinding,OriginalTurnFailure};
use semio_framework_value::{RetirementDemand,RetainedCloneStep,ValueError,ValueRefusalKind,retained_clone::NativeAllocationIdentity};
use crate::command_admission::{adopted,built,built_with,construction,fixed,paid,receipt,retired,stepped,unbuilt};
use std::mem::{ManuallyDrop,size_of};
/// 🏛️ The source pins its authentic catalog allocation, borrowed verb, caller and decoder until the original lease transfers or closes.
pub struct OriginalToolQualification{binding:OriginalSourceBinding,decoder:(NativeAllocationIdentity,u64),body:usize,verb:(usize,usize),alias:ManuallyDrop<Option<DeclaredToolCatalogAlias>>,registration:ManuallyDrop<Option<DeclaredToolRegistrationAlias>>,selected:Option<DeclaredToolRowKey>,role:DeclaredToolRole,ordinal:usize,offset:usize,phase:u8,closing:bool,construction:OriginalConstructionAdmission}
fn invalid()->ValueError{ValueError::literal(ValueRefusalKind::InvariantViolated,"tool qualification requires its original catalog, verb and receiving continuation")}
const SEARCH:usize=size_of::<(DeclaredToolRole,usize,usize,u8,Option<DeclaredToolRowKey>)>();
impl OriginalToolQualification{
 pub fn birth_demands()->RetirementDemand{let mut d=DeclaredToolCatalogAlias::birth_demands();d.copy_bytes+=size_of::<Self>()+size_of::<Option<Box<Self>>>();d.capacity_bytes=size_of::<Self>();d}
 /// 🌱️ One original metadata alias is retained before the bounded search starts.
 pub fn admit(source:DeclaredToolCatalogSource<'_>,verb:&str,cx:&mut StepContext<'_>,admission:&mut OriginalConstructionAdmission,output:&mut Option<Box<Self>>)->Result<bool,OriginalTurnFailure>{let d=Self::birth_demands();let binding=OriginalSourceBinding::borrow(cx);let body=cx.retained_grant().maximum_copy_bytes;let settled=built_with(cx,admission,output,construction(d),|control|{let decoder=(control.ledger_identity(),control.retirement_recipient_identity().ok_or_else(invalid)?);let g=semio_framework_value::RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:DeclaredToolCatalogAlias::birth_demands().copy_bytes,maximum_capacity_bytes:0,maximum_release_bytes:0,maximum_depth:1};let(alias,_)=DeclaredToolCatalogAlias::admit(source,g)?.ok_or_else(invalid)?;Ok((Box::write(Box::new_uninit(),Self{binding,decoder,body,verb:(verb.as_ptr()as usize,verb.len()),alias:ManuallyDrop::new(Some(alias)),registration:ManuallyDrop::new(None),selected:None,role:DeclaredToolRole::App,ordinal:0,offset:0,phase:0,closing:false,construction:Default::default()}),receipt(d)))})?;Ok(adopted(settled,admission,output,|owner|&mut owner.construction))}
 fn validate(&self,cx:&StepContext<'_>)->Result<(),OriginalTurnFailure>{if !self.binding.matches(cx)||cx.native_receiving_identity()!=Some(self.decoder){return Err(invalid().into())}Ok(())}
 fn row_id(&self)->Result<Option<&str>,ValueError>{let catalog=self.alias.as_ref().and_then(DeclaredToolCatalogAlias::catalog).ok_or_else(invalid)?;Ok(match self.role{DeclaredToolRole::App=>catalog.app.get(self.ordinal).map(|(id,_)|id.as_str()),DeclaredToolRole::Framework=>catalog.framework.get(self.ordinal).map(|(id,_)|id.as_str()),DeclaredToolRole::Bounded=>return Err(invalid())})}
 pub fn demands(&self,verb:&str)->Result<RetirementDemand,ValueError>{if self.verb!=(verb.as_ptr()as usize,verb.len()){return Err(invalid())}if self.closing{return self.close_demands()}match self.phase{0=>{let count=self.row_id()?.filter(|id|id.len()==verb.len()).map_or(0,|id|(id.len()-self.offset).min(64));Ok(RetirementDemand{copy_bytes:SEARCH+count,depth:1,..Default::default()})},1=>{let mut d=DeclaredToolRegistrationAlias::adoption_demands();d.copy_bytes+=size_of::<u8>();Ok(d)},2=>Ok(fixed::<(Option<DeclaredToolRegistrationAlias>,Option<DeclaredToolRegistrationAlias>,u8)>()),_=>Err(invalid())}}
 /// 🔎️ Each comparison borrows at most sixty-four bytes from one authentic declared row.
 pub fn advance(&mut self,verb:&str,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{self.validate(cx)?;let d=self.demands(verb)?;if self.closing{return Err(invalid().into())}if self.ready(){return Ok(true)}stepped(cx,self,|s|&mut s.construction,d,|s|{match s.phase{0=>{let id=s.row_id()?;if let Some(id)=id{let count=if id.len()==verb.len(){(id.len()-s.offset).min(64)}else{0};let equal=id.len()==verb.len()&&id.as_bytes()[s.offset..s.offset+count]==verb.as_bytes()[s.offset..s.offset+count];if equal&&s.offset+count==verb.len(){s.selected=s.alias.as_ref().and_then(DeclaredToolCatalogAlias::source).ok_or_else(invalid)?.row_key(s.role,s.ordinal)?;if s.selected.is_none(){return Err(invalid())}s.phase=1;}else if equal{s.offset+=count;}else{s.ordinal+=1;s.offset=0;}}else if s.role==DeclaredToolRole::App{s.role=DeclaredToolRole::Framework;s.ordinal=0;s.offset=0;}else{return Err(ValueError::literal(ValueRefusalKind::InvalidValue,"command has no authentic registered application or framework producer"))}},1=>{let g=semio_framework_value::RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes-size_of::<u8>(),maximum_capacity_bytes:0,maximum_release_bytes:0,maximum_depth:1};let(registration,_)=DeclaredToolRegistrationAlias::adopt(&mut s.alias,s.selected.ok_or_else(invalid)?,g)?.ok_or_else(invalid)?;*s.registration=Some(registration);s.phase=2;},_=>return Err(invalid())}Ok(receipt(d))})?;Ok(self.ready())}
 pub fn ready(&self)->bool{!self.closing&&self.phase==2}
 pub fn registration(&self)->Option<&DeclaredToolRegistrationAlias>{self.registration.as_ref()}
 pub fn take_demands(&self)->Result<RetirementDemand,ValueError>{if !self.ready(){return Err(invalid())}Ok(fixed::<(Option<DeclaredToolRegistrationAlias>,Option<DeclaredToolRegistrationAlias>,u8)>())}
 /// 🤝️ The same sole catalog alias transfers to the canonical admitted proof without cloning registration metadata.
 pub fn take_into(&mut self,output:&mut Option<DeclaredToolRegistrationAlias>,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{self.validate(cx)?;if output.is_some(){return Err(invalid().into())}let d=self.take_demands()?;built(cx,&mut self.construction,output,construction(d),||{let registration=self.registration.take().ok_or_else(invalid)?;self.phase=3;Ok((registration,receipt(d)))})}
 pub fn close_demands(&self)->Result<RetirementDemand,ValueError>{if !self.closing{return Ok(fixed::<bool>())}if let Some(registration)=self.registration.as_ref(){return if registration.terminal_is_empty(){Ok(fixed::<Option<DeclaredToolRegistrationAlias>>())}else{registration.close_demands(self.body)}}if let Some(alias)=self.alias.as_ref(){return if alias.terminal_is_empty(){Ok(fixed::<Option<DeclaredToolCatalogAlias>>())}else{alias.close_demands(self.body)}}Ok(Default::default())}
 pub fn close_step(&mut self,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{
  self.validate(cx)?;if self.terminal_is_empty(){return Ok(true)}if self.alias.is_none()&&self.registration.is_none(){return unbuilt(cx,&mut self.construction)}
  let d=self.close_demands()?;retired(cx,d,|effect|{if !self.closing{self.closing=true;return paid(effect,||RetainedCloneStep::Progress(receipt(d)))}if let Some(registration)=self.registration.as_mut(){if registration.terminal_is_empty(){self.registration.take();return paid(effect,||RetainedCloneStep::Progress(receipt(d)))}return registration.close_step(effect)}if let Some(alias)=self.alias.as_mut(){if alias.terminal_is_empty(){self.alias.take();return paid(effect,||RetainedCloneStep::Progress(receipt(d)))}return alias.close_step(effect)}Ok(RetainedCloneStep::Complete(Default::default()))})?;Ok(self.terminal_is_empty())
 }
 pub fn terminal_is_empty(&self)->bool{self.alias.is_none()&&self.registration.is_none()&&self.construction.terminal_is_empty()}
 pub fn release_demands()->RetirementDemand{RetirementDemand{release_bytes:size_of::<Self>(),depth:1,..Default::default()}}
}
impl Drop for OriginalToolQualification{fn drop(&mut self){assert!(std::thread::panicking()||self.terminal_is_empty(),"native tool qualification must return its original metadata alias before Drop")}}
